// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;

    function setUp() public {
        c = new PrivatePool(address(this), address(this), address(this));
    }

    function testFuzz_property(
        address baseToken,
        address nft,
        uint256 virtualBase,
        uint256 virtualNft,
        uint256 changeFeeValue,
        uint256 feeRate,
        bytes32 merkleRoot,
        bool useOracle,
        bool payRoyalties
    ) public {
        // keep params in the admissible domain (wide)
        virtualBase = bound(virtualBase, 0, type(uint128).max);
        virtualNft = bound(virtualNft, 0, type(uint128).max);
        changeFeeValue = bound(changeFeeValue, 0, type(uint56).max);
        feeRate = bound(feeRate, 0, 5_000);

        c.initialize(
            baseToken,
            nft,
            uint128(virtualBase),
            uint128(virtualNft),
            uint56(changeFeeValue),
            uint16(feeRate),
            merkleRoot,
            useOracle,
            payRoyalties
        );

        // General rule: after initialize, the stored changeFee equals the supplied _changeFee.
        assertTrue(c.changeFee() == uint56(changeFeeValue));
    }
}
